#pragma once

#include <string>
#include <string_view>

namespace pvz::engine {

// Maps an original `ZombieClass` (e.g. `ZombieZombossMech_Egypt`) to one of the six
// behaviour families the kernel implements (`walk`, `jump`, `steal`, `summon`,
// `gargantuar`, `fly`). The table is generated by `tools/contentc/zclasses.py` from
// the original sheets (`pkg_2115` / `pkg_2111` / `pkg_2112`) and embedded at build
// time, so a pack-only zombie type still gets a real behaviour instead of `walk`.
//
// Returns an empty view when the class is unknown; callers keep their previous
// decision (content `behavior`, else `walk`) and count it as unwired.
std::string_view zombieFamilyFor(std::string_view className);

// Number of rows in the generated table; 183 for the 26.10.1 sheets. Exposed so
// tests and the coverage report can prove the table was actually linked in.
std::size_t zombieFamilyCount();

}  // namespace pvz::engine
